def _is_int(v):
    return isinstance(v, int) and not isinstance(v, bool)


def _one_line(value):
    return isinstance(value, str) and "\n" not in value and "\r" not in value


class Ledger:
    def __init__(self, chart=None, rates=None):
        self.chart = chart if chart is not None else Chart()
        self.rates = rates if rates is not None else RateTable()
        self._txs = {}
        self._max_id = 0

    def __len__(self):
        return len(self._txs)

    # -- validation -----------------------------------------------------
    def _prepare(self, tx, ids_in_use):
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: %r" % (tx,))
        if not is_date(tx.date):
            raise LedgerError("transaction date must be a date, not %r" % (tx.date,))
        if tx.flag not in ("*", "!") or not isinstance(tx.flag, str):
            raise LedgerError("invalid flag %r: use * or !" % (tx.flag,))
        if not _one_line(tx.payee):
            raise LedgerError("payee must be text without a line break")
        if not _one_line(tx.narration):
            raise LedgerError("narration must be text without a line break")
        if not isinstance(tx.tags, (list, tuple, set, frozenset)):
            raise LedgerError("tags must be a list of names")
        for tag in tx.tags:
            if not isinstance(tag, str) or not _TAG.fullmatch(tag):
                raise LedgerError("invalid tag %r" % (tag,))
        if not isinstance(tx.postings, (list, tuple)):
            raise LedgerError("postings must be a list")
        postings = list(tx.postings)
        if len(postings) < 2:
            raise LedgerError("a transaction needs at least two postings")
        for p in postings:
            if not isinstance(p, Posting):
                raise LedgerError("not a posting: %r" % (p,))
            if not _one_line(p.note):
                raise LedgerError("a posting note must be text without a line break")
            if p.amount is not None and not isinstance(p.amount, Money):
                raise LedgerError("a posting amount must be money or None")
        for p in postings:
            if not self.chart.exists(p.account):
                raise LedgerError("unknown account %s" % (p.account,))
            if not self.chart.is_open(p.account, tx.date):
                raise LedgerError("account %s is not open on %s" % (p.account, format_date(tx.date)))
            self._check_currency(p.account, p.amount)
        missing = [i for i, p in enumerate(postings) if p.amount is None]
        if len(missing) > 1:
            raise LedgerError("more than one posting without an amount")
        sums = {}
        for p in postings:
            if p.amount is not None:
                sums[p.amount.currency] = sums.get(p.amount.currency, 0) + p.amount.minor
        off = sorted(c for c, v in sums.items() if v != 0)
        if missing:
            if not off:
                raise LedgerError("nothing to infer: the other postings already balance")
            i = missing[0]
            gap = postings[i]
            filled = []
            for cur in off:
                amount = Money(-sums[cur], cur)
                self._check_currency(gap.account, amount)
                filled.append(Posting(gap.account, amount, gap.note))
            postings[i:i + 1] = filled
        elif off:
            raise LedgerError("transaction does not balance: " + ", ".join(
                "%s %s" % (c, format_minor(sums[c], c)) for c in off))
        if tx.id is None:
            new_id = self._max_id + 1
        else:
            if not _is_int(tx.id) or tx.id < 1:
                raise LedgerError("invalid transaction id %r" % (tx.id,))
            if tx.id in ids_in_use:
                raise LedgerError("transaction id %d already exists" % tx.id)
            new_id = tx.id
        return Transaction(tx.date, tx.payee, tx.narration, postings,
                           tuple(sorted(set(tx.tags))), tx.flag, new_id)

    def _check_currency(self, account, amount):
        if amount is None:
            return
        held = self.chart.get(account).currency
        if held is not None and held != amount.currency:
            raise LedgerError("account %s only holds %s, not %s" % (account, held, amount.currency))

    def _store(self, stored):
        self._txs[stored.id] = stored
        if stored.id > self._max_id:
            self._max_id = stored.id

    # -- changing ---------------------------------------------------------
    def add(self, tx):
        stored = self._prepare(tx, self._txs)
        self._store(stored)
        return stored

    def add_many(self, transactions):
        snapshot = (dict(self._txs), self._max_id)
        out = []
        try:
            for tx in transactions:
                out.append(self.add(tx))
        except BaseException:
            self._txs, self._max_id = snapshot
            raise
        return out

    def replace(self, id, tx):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        if not isinstance(tx, Transaction):
            raise LedgerError("not a transaction: %r" % (tx,))
        if tx.id is not None and tx.id != id:
            raise LedgerError("transaction id %s does not match %s" % (tx.id, id))
        probe = Transaction(tx.date, tx.payee, tx.narration, tx.postings, tx.tags, tx.flag, None)
        stored = self._prepare(probe, self._txs)
        stored.id = id
        self._txs[id] = stored
        return stored

    def remove(self, id):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        return self._txs.pop(id)

    # -- reading ------------------------------------------------------------
    def get(self, id):
        if id not in self._txs:
            raise NotFoundError("no transaction %s" % (id,))
        return self._txs[id]

    def transactions(self):
        return sorted(self._txs.values(), key=lambda t: (t.date, t.id))

    def postings(self):
        for tx in self.transactions():
            for p in tx.postings:
                yield tx, p

    def _sums(self, as_of, rollup):
        if as_of is not None and not is_date(as_of):
            raise LedgerError("as_of must be a date, not %r" % (as_of,))
        out = {}
        for tx, p in self.postings():
            if as_of is not None and tx.date > as_of:
                continue
            if p.amount is None:
                continue
            path = p.account
            while path is not None:
                cur = out.setdefault(path, {})
                cur[p.amount.currency] = cur.get(p.amount.currency, 0) + p.amount.minor
                path = parent_path(path) if rollup else None
        return out

    def _clean(self, sums):
        out = {}
        for account, cur in sums.items():
            kept = {c: v for c, v in cur.items() if v != 0}
            if kept:
                out[account] = kept
        return out

    def balances(self, as_of=None):
        return self._clean(self._sums(as_of, False))

    def rollup_balances(self, as_of=None):
        return self._clean(self._sums(as_of, True))

    def balance(self, account, as_of=None, currency=None, rollup=True):
        if not self.chart.exists(account):
            raise NotFoundError("no such account: %s" % (account,))
        table = self.rollup_balances(as_of) if rollup else self.balances(as_of)
        mine = table.get(account, {})
        if currency is not None:
            return Money(mine.get(currency, 0), currency)
        return {c: Money(v, c) for c, v in mine.items()}
