# -- plumbing ----------------------------------------------------------
def _live(self):
    if self._closed:
        raise ConflictError("the book is closed")
    return self._conn

@property
def version(self):
    with self._lock:
        conn = self._live()
        try:
            return conn.execute("PRAGMA user_version").fetchone()[0]
        except sqlite3.Error as exc:
            raise _map_error(exc)

@staticmethod
def _require_current(conn):
    v = conn.execute("PRAGMA user_version").fetchone()[0]
    if v < LATEST_VERSION:
        raise ConflictError("database is at version %d, run `tallybook db migrate`" % v)
    if v > LATEST_VERSION:
        raise ConflictError("database is at version %d, newer than this tallybook (version %d)"
                            % (v, LATEST_VERSION))

@contextlib.contextmanager
def _tx(self, write=False):
    """A transaction on the current-version book; rolls back on any error."""
    with self._lock:
        conn = self._live()
        try:
            conn.execute("BEGIN IMMEDIATE" if write else "BEGIN")
        except sqlite3.Error as exc:
            raise _map_error(exc)
        try:
            self._require_current(conn)
            yield conn
            # a read-only transaction has nothing to commit; ending it with ROLLBACK
            # cannot fail, even on a damaged file that `check` is inspecting
            conn.execute("COMMIT" if write else "ROLLBACK")
        except BaseException as exc:
            try:
                conn.execute("ROLLBACK")
            except sqlite3.Error:
                pass
            if isinstance(exc, sqlite3.Error):
                raise _map_error(exc) from None
            raise

# -- migration -----------------------------------------------------------
def migrate(self):
    applied = []
    with self._lock:
        conn = self._live()
        while True:
            try:
                v = conn.execute("PRAGMA user_version").fetchone()[0]
            except sqlite3.Error as exc:
                raise _map_error(exc)
            if v > LATEST_VERSION:
                raise ConflictError("database is at version %d, newer than this tallybook (version %d)"
                                    % (v, LATEST_VERSION))
            if v == LATEST_VERSION:
                return applied
            n = v + 1
            try:
                conn.execute("BEGIN IMMEDIATE")
                try:
                    again = conn.execute("PRAGMA user_version").fetchone()[0]
                    if again == v:
                        _STEPS[n](conn)
                        conn.execute("PRAGMA user_version = %d" % n)
                    conn.execute("COMMIT")
                except BaseException:
                    try:
                        conn.execute("ROLLBACK")
                    except sqlite3.Error:
                        pass
                    raise
            except (sqlite3.Error, _StepFailed, OverflowError) as exc:
                raise ConflictError("migration to version %d failed: %s" % (n, exc)) from None
            if again == v:
                applied.append(n)

