# -- transactions ----------------------------------------------------------
@staticmethod
def _next_id(c):
    seq = 0
    has_seq = c.execute("SELECT 1 FROM sqlite_master WHERE name = 'sqlite_sequence'").fetchone()
    if has_seq:
        row = c.execute("SELECT seq FROM sqlite_sequence WHERE name = 'transactions'").fetchone()
        if row and _is_int(row[0]):
            seq = row[0]
    top = c.execute("SELECT COALESCE(MAX(id), 0) FROM transactions").fetchone()[0]
    return max(seq, top) + 1

def _validate_batch(self, c, led, items):
    """items: [(index, tx)]; returns the stored transactions with fresh ids."""
    next_id = self._next_id(c)
    stored = []
    for index, tx in items:
        try:
            if not isinstance(tx, Transaction):
                raise LedgerError("not a transaction: %r" % (tx,))
            probe = Transaction(tx.date, tx.payee, tx.narration, tx.postings, tx.tags, tx.flag, next_id)
            stored.append(led.add(probe))
        except TallybookError as exc:
            exc.detail["index"] = index
            raise
        next_id += 1
    return stored

def _insert_transactions(self, c, stored, keys=None):
    known = {r[0] for r in c.execute("SELECT path FROM accounts")}
    for tx in stored:
        for p in tx.postings:
            if p.account not in known:
                # a posting to a parent that only exists implicitly: store it so the
                # foreign key holds (the parent keeps no currency, dates or note)
                self._insert_account(c, Account(p.account, account_type(p.account)))
                known.add(p.account)
        c.execute("INSERT INTO transactions (id, date, payee, narration, cleared, flag) VALUES (?,?,?,?,?,?)",
                  (tx.id, format_date(tx.date), tx.payee, tx.narration,
                   1 if tx.flag == "*" else 0, tx.flag))
        c.executemany("INSERT INTO postings (tx_id, seq, account, minor, currency, note) VALUES (?,?,?,?,?,?)",
                      [(tx.id, i, p.account, _enc_int(p.amount.minor), p.amount.currency, p.note)
                       for i, p in enumerate(tx.postings)])
        c.executemany("INSERT INTO tags (tx_id, tag) VALUES (?, ?)", [(tx.id, t) for t in tx.tags])
    if keys:
        for tx, key in zip(stored, keys):
            if key is not None:
                c.execute("INSERT INTO import_keys (key, tx_id) VALUES (?, ?)", (key, tx.id))

def add_transaction(self, tx):
    with self._tx(write=True) as c:
        led = Ledger(self._chart(c), self._rate_table(c))
        stored = self._validate_batch(c, led, [(0, tx)])
        self._insert_transactions(c, stored)
        return stored[0]

def add_transactions(self, txs, keys=None):
    txs = list(txs)
    if keys is not None:
        keys = list(keys)
        if len(keys) != len(txs) or not all(isinstance(k, str) for k in keys):
            raise ValidationError("keys must be one text per transaction")
    with self._tx(write=True) as c:
        led = Ledger(self._chart(c), self._rate_table(c))
        skipped = []
        items = []
        item_keys = []
        seen = set()
        for i, tx in enumerate(txs):
            if keys is not None:
                key = keys[i]
                if key in seen or c.execute("SELECT 1 FROM import_keys WHERE key = ?", (key,)).fetchone():
                    skipped.append(i)
                    continue
                seen.add(key)
                item_keys.append(key)
            items.append((i, tx))
        stored = self._validate_batch(c, led, items)
        self._insert_transactions(c, stored, item_keys if keys is not None else None)
        return BulkAdd(added=stored, skipped=skipped)

def _compile_query(self, query, chart_source):
    """Returns None for 'everything', else a Query."""
    mod = _query_mod()
    if query is None:
        return None
    if isinstance(query, mod.Query):
        return None if query.is_empty else query
    if not isinstance(query, str):
        raise ValidationError("a query must be text or a parsed Query")
    if query.strip() == "":
        return None
    return mod.parse_query(query, chart_source())

def transactions(self, query=None, limit=None, offset=0):
    if limit is not None:
        _nonneg(limit, "limit")
    _nonneg(offset, "offset")
    with self._tx() as c:
        q = self._compile_query(query, lambda: self._chart(c))
        if q is None:
            rows = c.execute(self._TX_COLUMNS + " ORDER BY date, id LIMIT ? OFFSET ?",
                             (-1 if limit is None else _sql_int(limit), _sql_int(offset))).fetchall()
            return self._hydrate(c, rows)
        found = [t for t in self._all_transactions(c) if q.matches(t)]
        end = None if limit is None else offset + limit
        return found[offset:end]

def count_transactions(self, query=None):
    with self._tx() as c:
        q = self._compile_query(query, lambda: self._chart(c))
        if q is None:
            return c.execute("SELECT count(*) FROM transactions").fetchone()[0]
        return sum(1 for t in self._all_transactions(c) if q.matches(t))

