def materialize(self, upto=None, today=None):
    for value, what in ((upto, "upto"), (today, "today")):
        if value is not None and not is_date(value):
            raise ValidationError("%s must be a date" % what)
    if upto is None and today is None:
        raise ValidationError("materialize needs upto or today")
    horizon = min(d for d in (upto, today) if d is not None)
    rmod = _recurring_mod()
    with self._tx(write=True) as c:
        items = []
        rows = self._recurring_rows(c)
        for pos, (rec, through) in enumerate(rows):
            first = rec.start
            if through is not None:
                if through >= date.max:
                    continue
                first = max(first, through + timedelta(days=1))
            if horizon < first:
                continue
            for day in rmod.occurrences(rec, first, horizon):
                items.append((day, rec.name, pos, rec))
        items.sort(key=lambda it: (it[0], it[1], it[2]))
        made = [(i, rmod.instantiate(rec, day)) for i, (day, _n, _p, rec) in enumerate(items)]
        led = Ledger(self._chart(c), self._rate_table(c))
        stored = self._validate_batch(c, led, made)
        self._insert_transactions(c, stored)
        for rec, through in rows:
            if through is None or horizon > through:
                c.execute("UPDATE recurring SET materialized_through = ? WHERE name = ?",
                          (format_date(horizon), rec.name))
        return stored

