def import_csv(self, text, profile, apply_rules=True):
    cmod = _csv_mod()
    if not isinstance(text, str):
        raise ValidationError("the CSV must be text")
    with self._tx(write=True) as c:
        if isinstance(profile, cmod.ImportProfile):
            prof = profile
        elif isinstance(profile, str):
            if _NAME_CHARS.fullmatch(profile):
                row = c.execute("SELECT value FROM settings WHERE key = ?", ("profile." + profile,)).fetchone()
                if row is None:
                    raise NotFoundError("no such profile: %s" % profile)
                prof = cmod.parse_profile(row[0])
            else:
                prof = cmod.parse_profile(profile)
        else:
            raise ValidationError("a profile must be a name, profile text or an ImportProfile")
        ruleset = None
        if apply_rules:
            row = c.execute("SELECT body FROM rules WHERE id = 1").fetchone()
            if row is not None and row[0].strip():
                ruleset = _rules_mod().parse_rules(row[0])
        existing = self._all_transactions(c)
        result = cmod.import_csv(text, prof, ruleset, existing)
        if result.errors:
            return ImportOutcome([], list(result.duplicates), list(result.errors))

        def base_key(tx):
            for p in tx.postings:
                if p.account == prof.account and p.amount is not None:
                    return "%s|%s|%s|%d %s" % (format_date(tx.date), tx.payee, prof.account,
                                                p.amount.minor, p.amount.currency)
            return None

        counts = {}
        for tx in result.duplicates:
            k = base_key(tx)
            counts[k] = counts.get(k, 0) + 1
        keys = []
        used = set()
        for tx in result.transactions:
            k = base_key(tx)
            n = counts.get(k, 0) + 1
            while True:
                full = "%s|%d" % (k, n)
                if full not in used and not c.execute("SELECT 1 FROM import_keys WHERE key = ?",
                                                      (full,)).fetchone():
                    break
                n += 1
            counts[k] = n
            used.add(full)
            keys.append(full)
        led = Ledger(self._chart(c), self._rate_table(c))
        stored = self._validate_batch(c, led, list(enumerate(result.transactions)))
        self._insert_transactions(c, stored, keys)
        return ImportOutcome(stored, list(result.duplicates), [])

